34. //==================================================================================================
35. // Memory Region Type
36. //==================================================================================================
37. 
38. ///
39. /// # Description
40. ///
41. /// A type that represents the type of a memory region.
42. ///
43. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
44. #[verus_verify]
45. pub enum MemoryRegionType {
46.     /// Usable memory.
47.     Usable,
48.     /// Reserved memory.
49.     Reserved,
50.     /// Memory mapped I/O.
51.     Mmio,
52.     /// Bad memory.
53.     Bad,
54. }
55. 
56. //==================================================================================================
57. // MMIO Cache Policy
58. //==================================================================================================
59. 
60. ///
61. /// # Description
62. ///
63. /// Caching policy for MMIO memory regions. Controls the PWT (Page Write-Through) and PCD
64. /// (Page Cache Disable) bits in the page table entries that back the region.
65. ///
66. #[verus_verify(external_derive)]
67. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
68. pub struct MmioCachePolicy {
69.     /// If `true`, the page is mapped with the Write-Through attribute (PWT=1).
70.     write_through: bool,
71.     /// If `true`, caching is enabled for the page (PCD=0).
72.     cache_enabled: bool,
73. }
74. 
75. impl MmioCachePolicy {
76.     ///
77.     /// # Description
78.     ///
79.     /// Creates a new MMIO cache policy.
80.     ///
81.     /// # Parameters
82.     ///
83.     /// - `write_through`: If `true`, enables the Write-Through attribute (PWT=1).
84.     /// - `cache_enabled`: If `true`, enables caching for the page (PCD=0).
85.     ///
86.     /// # Returns
87.     ///
88.     /// A new [`MmioCachePolicy`] instance.
89.     ///
90.     pub const fn new(write_through: bool, cache_enabled: bool) -> Self {
91.         Self {
92.             write_through,
93.             cache_enabled,
94.         }
95.     }
96. 
97.     /// Uncacheable: Write-Through Enabled, Cache Disabled.
98.     pub const UNCACHEABLE: Self = Self {
99.         write_through: true,
100.         cache_enabled: false,
101.     };
102. 
103.     /// Write-Back: Write-Through Disabled, Cache Enabled.
104.     pub const WRITE_BACK: Self = Self {
105.         write_through: false,
106.         cache_enabled: true,
107.     };
108. 
109.     ///
110.     /// # Description
111.     ///
112.     /// Returns whether the Write-Through attribute is set.
113.     ///
114.     /// # Returns
115.     ///
116.     /// `true` if the page is mapped with the Write-Through attribute (PWT=1).
117.     ///
118.     pub fn write_through(&self) -> bool {
119.         self.write_through
120.     }
121. 
122.     ///
123.     /// # Description
124.     ///
125.     /// Returns whether caching is enabled.
126.     ///
127.     /// # Returns
128.     ///
129.     /// `true` if caching is enabled for the page (PCD=0).
130.     ///
131.     pub fn cache_enabled(&self) -> bool {
132.         self.cache_enabled
133.     }
134. }
135. //==================================================================================================
136. // Memory Region
137. //==================================================================================================
138. 
139. ///
140. /// # Description
141. ///
142. /// A memory region.
143. ///
144. #[verus_verify(external_derive)]
145. #[derive(Debug, Clone)]
146. pub struct MemoryRegion<T: Address> {
147.     name: String,
148.     start: T,
149.     size: usize,
150.     typ: MemoryRegionType,
151.     perm: AccessPermission,
152.     cache_policy: Option<MmioCachePolicy>,
153. }
154. 
155. impl<T: Address> MemoryRegion<T> {
156.     /// Maximum byte-length of a memory region name.
157.     const MEMORY_REGION_NAME_MAX: usize = 32;
158. 
159.     /// Creates a new memory region.
160.     pub fn new(
161.         name: &str,
162.         start: T,
163.         size: usize,
164.         typ: MemoryRegionType,
165.         perm: AccessPermission,
166.     ) -> Result<Self, Error> {
167.         // Check if name is too long (byte length).
168.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
169.             let reason: &str = "memory region name is too long";
170.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
171.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
172.         }
173. 
174.         // Check if size of the memory region is valid.
175.         if size == 0 {
176.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
177.         }
178. 
179.         // Check if memory region is too big.
180.         let start_raw_addr: usize = start.clone().into_raw_value();
181.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
182.             Some(end_raw_addr) => end_raw_addr,
183.             None => {
184.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
185.             },
186.         };
187. 
188.         // Check if memory region spans outside the address space.
189.         if end_raw_addr > T::max_addr() {
190.             return Err(Error::new(
191.                 ErrorCode::InvalidArgument,
192.                 "memory region spans outside the address space",
193.             ));
194.         }
195. 
196.         Ok(Self {
197.             name: name.to_string(),
198.             start,
199.             size,
200.             typ,
201.             perm,
202.             cache_policy: None,
203.         })
204.     }
205. 
206.     pub fn name(&self) -> String {
207.         self.name.clone()
208.     }
209. 
210.     /// Returns the first valid address that lies in the target memory region.
211.     pub fn start(&self) -> T {
212.         self.start.clone()
213.     }
214. 
215.     /// Returns the size of the target memory region.
216.     pub fn size(&self) -> usize {
217.         self.size
218.     }
219. 
220.     /// Returns the type of the target memory region.
221.     pub fn typ(&self) -> MemoryRegionType {
222.         self.typ
223.     }
224. 
225.     /// Returns the permissions of the target memory region.
226.     pub fn perm(&self) -> AccessPermission {
227.         self.perm
228.     }
229. 
230.     ///
231.     /// # Description
232.     ///
233.     /// Returns the MMIO cache policy of the target memory region, if set.
234.     ///
235.     /// # Returns
236.     ///
237.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
238.     ///
239.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
240.         self.cache_policy
241.     }
242. 
243.     ///
244.     /// # Description
245.     ///
246.     /// Sets the MMIO cache policy of the target memory region.
247.     ///
248.     /// # Parameters
249.     ///
250.     /// - `policy`: The cache policy to assign.
251.     ///
252.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
253.         self.cache_policy = Some(policy);
254.     }
255. }
256. 
257. impl<T: Address> PartialEq for MemoryRegion<T> {
258.     fn eq(&self, other: &Self) -> bool {
259.         self.name == other.name
260.             && self.start == other.start
261.             && self.size == other.size
262.             && self.typ == other.typ
263.             && self.perm == other.perm
264.             && self.cache_policy == other.cache_policy
265.     }
266. }
267. 
268. impl<T: Address> Eq for MemoryRegion<T> {}
269. 
270. impl<T: Address> PartialOrd for MemoryRegion<T> {
271.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
272.         Some(self.cmp(other))
273.     }
274. }
275. 
276. impl<T: Address> Ord for MemoryRegion<T> {
277.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
278.         self.start.cmp(&other.start)
279.     }
280. }
281. 
282. //==================================================================================================
283. // Truncated Memory Region
284. //==================================================================================================
285. 
286. ///
287. /// # Description
288. ///
289. /// A memory region that has been truncated to a multiple of a page size.
290. ///
291. #[verus_verify(external_derive)]
292. #[derive(Clone)]
293. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
294. 
295. impl<T: Address> TruncatedMemoryRegion<T> {
296.     /// Creates a new truncated memory region.
297.     pub fn new(
298.         name: &str,
299.         start: PageAligned<T>,
300.         size: usize,
301.         typ: MemoryRegionType,
302.         perm: AccessPermission,
303.     ) -> Result<Self, Error> {
304.         // Truncate the size of the memory region to a multiple of the page size.
305.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
306.             let reason: &str = "align_up overflow";
307.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
308.             Error::new(ErrorCode::InvalidArgument, reason)
309.         })?;
310.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
311.     }
312. 
313.     ///
314.     /// # Description
315.     ///
316.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
317.     ///
318.     /// # Parameters
319.     ///
320.     /// - `name`: Name of the memory region.
321.     /// - `start`: Page-aligned start address.
322.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
323.     /// - `perm`: Access permissions for the region.
324.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
325.     ///
326.     /// # Returns
327.     ///
328.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
329.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
330.     ///
331.     pub fn new_mmio(
332.         name: &str,
333.         start: PageAligned<T>,
334.         size: usize,
335.         perm: AccessPermission,
336.         cache_policy: MmioCachePolicy,
337.     ) -> Result<Self, Error> {
338.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
339.         region.0.set_cache_policy(cache_policy);
340.         Ok(region)
341.     }
342. 
343.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
344.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
345.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
346.         let start: PageAligned<T> = PageAligned::from_address(start)?;
347.         let name: String = region.name();
348.         let size: usize = region.size();
349.         let typ: MemoryRegionType = region.typ();
350.         let perm: AccessPermission = region.perm();
351.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
352.         if let Some(policy) = cache_policy {
353.             truncated.0.set_cache_policy(policy);
354.         }
355.         Ok(truncated)
356.     }
357. 
358.     pub fn name(&self) -> String {
359.         self.0.name()
360.     }
361. 
362.     /// Returns the first valid address that lies in the target memory region.
363.     pub fn start(&self) -> PageAligned<T> {
364.         self.0.start()
365.     }
366. 
367.     /// Returns the size of the target memory region.
368.     pub fn size(&self) -> usize {
369.         self.0.size()
370.     }
371. 
372.     /// Returns the type of the target memory region.
373.     pub fn typ(&self) -> MemoryRegionType {
374.         self.0.typ()
375.     }
376. 
377.     /// Returns the permissions of the target memory region.
378.     pub fn perm(&self) -> AccessPermission {
379.         self.0.perm()
380.     }
381. 
382.     ///
383.     /// # Description
384.     ///
385.     /// Returns the MMIO cache policy of the target memory region, if set.
386.     ///
387.     /// # Returns
388.     ///
389.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
390.     ///
391.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
392.         self.0.cache_policy()
393.     }
394. }
395. 
396. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
397.     fn eq(&self, other: &Self) -> bool {
398.         self.0 == other.0
399.     }
400. }
401. 
402. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
403. 
404. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
405.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
406.         Some(self.cmp(other))
407.     }
408. }
409. 
410. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
411.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
412.         self.0.cmp(&other.0)
413.     }
414. }
415. 
416. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
417.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
418.         write!(
419.             f,
420.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
421.              cache_policy: {:?} }}",
422.             self.name(),
423.             self.start(),
424.             self.size(),
425.             self.typ(),
426.             self.perm(),
427.             self.cache_policy()
428.         )
429.     }
430. }
431. 
432. //==================================================================================================
433. // Standalone Functions
434. //==================================================================================================
435. 
436. impl TruncatedMemoryRegion<PhysicalAddress> {
437.     /// Attempts to create a virtual memory region from a physical memory region.
438.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
439.         let name: String = region.name();
440.         let start: PageAligned<PhysicalAddress> =
441.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
442.         let size: usize = region.size();
443.         let typ: MemoryRegionType = region.typ();
444.         let perm: AccessPermission = region.perm();
445.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
446.     }
447. }
448. 
