             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
             Error::new(ErrorCode::InvalidArgument, reason)
         })?;
         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
     }

